 const categories={costs:'Стоимость развития',merits:'Достоинства и недостатки',gifts:'Дары смертным',earthbound:'Привязанные к Земле',rituals:'Ритуалы',bookmarks:'Закладки',storyteller:'Рассказчику',adversaries:'Противники',actions:'Действия',combat:'Бой',equipment:'Оружие и броня',health:'Ранения и восстановление',hazards:'Опасности',conditions:'Игровые состояния',possession:'Смена носителя',houses:'Дома падших',backgrounds:'Детали биографии',archetypes:'Натуры и Маски',abilities:'Способности',creation:'Создание персонажа',attributes:'Атрибуты',overview:'Обзор',knowledge:'Знания',forms:'Апокалиптические формы',rules:'Правила и уточнения',sources:'Библиотека',coverage:'Карта наполнения',resources:'Вера и личность',faith:'Вера и договоры',names:'Имена и призыв',innate:'Врождённые способности'};
