 const isRule=e=>!extendedSections.has(e.section)&&!isKnowledgeGuide(e)&&!isHouse(e)&&!isBackground(e)&&!isArchetype(e)&&!isAbility(e)&&!isFaith(e)&&!isNames(e)&&!isCreation(e)&&!isAttribute(e)&&!['evocation','form','innate','resource'].includes(e.type);
 const counts={storyteller:D.entries.filter(e=>e.section==='storyteller').length,adversaries:D.entries.filter(e=>e.section==='adversaries').length,actions:D.entries.filter(e=>e.section==='actions').length,combat:D.entries.filter(e=>e.section==='combat').length,equipment:D.entries.filter(e=>e.section==='equipment').length,health:D.entries.filter(e=>e.section==='health').length,conditions:D.entries.filter(e=>e.section==='conditions'||e.condition_group==='combat').length,houses:D.entries.filter(e=>isHouse(e)&&!e.id.endsWith('-overview')).length,backgrounds:D.entries.filter(e=>isBackground(e)&&!e.id.endsWith('-overview')).length,archetypes:D.entries.filter(e=>isArchetype(e)&&e.id!=='dtf-classic-core-ru-archetype-overview').length,abilities:D.entries.filter(e=>isAbility(e)&&!abilityIntros.has(e.id)).length,creation:D.entries.filter(isCreation).length,attributes:D.entries.filter(isAttribute).length,names:D.entries.filter(isNames).length,faith:D.entries.filter(isFaith).length,knowledge:D.entries.filter(e=>e.type==='evocation').length,forms:D.entries.filter(e=>e.type==='form').length,resources:D.entries.filter(e=>e.type==='resource'||e.section==='resources').length,innate:D.entries.filter(e=>e.type==='innate'||e.section==='innate').length,rules:D.entries.filter(isRule).length,sources:D.library.length};
 document.querySelectorAll('aside nav a').forEach(n=>{const c=n.querySelector('span');if(c&&counts[n.hash.slice(1)]!==undefined)c.textContent=counts[n.hash.slice(1)]});
