  return {export:()=>JSON.stringify({format:'dtf-collections',version:1,groups},null,2),import(text){const data=JSON.parse(text);if(data?.format!=='dtf-collections'||data.version!==1||!Array.isArray(data.groups)||data.groups.length>100)throw Error('Неверный формат файла подборок.');const incoming=data.groups.map(g=>{if(!g||typeof g.name!=='string'||!g.name.trim()||!Array.isArray(g.items)||g.items.length>2000||g.items.some(id=>typeof id!=='string'))throw Error('Повреждённая подборка.');return {name:g.name.trim().slice(0,80),items:[...new Set(g.items.filter(valid))]}});let skipped=0;incoming.forEach((g,i)=>{skipped+=data.groups[i].items.filter(id=>!valid(id)).length;const id=this.create(g.name);groups.find(x=>x.id===id).items=g.items});save();return {count:incoming.length,skipped}},remove(id){groups=groups.filter(g=>g.id!==id);save()},list:()=>groups.map(g=>({...g,items:[...g.items]})),persistent:()=>persistent,create(name){name=name.trim().slice(0,80);if(!name)return null;let id='set-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);groups.push({id,name,items:[]});save();return id},rename(id,name){const g=groups.find(g=>g.id===id);if(g&&name.trim()){g.name=name.trim().slice(0,80);save()}},toggle(id,item){const g=groups.find(g=>g.id===id);if(!g||!valid(item))return;g.items=g.items.includes(item)?g.items.filter(x=>x!==item):[...g.items,item];save()}};
